#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

# Values are remembered here between runs (git-ignored; nothing in it is secret)
ENV_FILE=".cloudflare-wizard.env"

# ── Helpers for this wizard ───────────────────────────────────────────────
FAILS=0
pass() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
fail() { printf '  %s✗ %s%s\n' "$YELLOW" "$1" "$RESET"; FAILS=$((FAILS + 1)); }

status_of()   { curl -s -o /dev/null -w '%{http_code}' --max-time 15 "$1" || echo 000; }
location_of() { curl -s -o /dev/null -w '%{redirect_url}' --max-time 15 "$1" || true; }
body_has()    { curl -s --max-time 15 "$1" | grep -q "$2"; }

# check_site BASE runs the same checks as #29's `wrangler dev` verification
check_site() {
  local base="$1"; FAILS=0
  [[ "$(status_of "$base/")" == 200 ]] && body_has "$base/" "Bloomington-Normal Developers" \
    && pass "home page loads" || fail "home page didn't load from $base/"
  [[ "$(status_of "$base/events/37")" == 200 ]] \
    && pass "an Event page loads (/events/37)" || fail "/events/37 didn't return 200"
  [[ "$(location_of "$base/events/37/")" == "$base/events/37" ]] \
    && pass "/events/37/ redirects to /events/37" || fail "/events/37/ didn't redirect to /events/37"
  [[ "$(status_of "$base/nope")" == 404 ]] && body_has "$base/nope" "404 - Page Not Found" \
    && pass "unknown paths get the custom 404 page" || fail "/nope didn't return the custom 404"
  [[ "$(status_of "$base/sitemap-index.xml")" == 200 ]] \
    && pass "sitemap is served" || fail "/sitemap-index.xml didn't return 200"
  (( FAILS == 0 ))
}

ns_of() { dig +short NS blono.dev @1.1.1.1 | sort | tr '\n' ' '; }

banner "blono.dev → Cloudflare, part 1: setup (issue #30)"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Preflight"
say "Part 1 connects the repo to Cloudflare and moves DNS there. The live site"
say "keeps serving from Vercel the whole time; nothing is cut over until part 2."
printf '\n'
for cmd in curl dig git; do
  command -v "$cmd" >/dev/null 2>&1 && pass "$cmd is installed" || { fail "$cmd is missing"; exit 1; }
done
[[ -f wrangler.jsonc ]] && pass "running from the blono.dev repo" \
  || { fail "run this from the repo root (wrangler.jsonc not found)"; exit 1; }
printf '\n'
say "Current DNS for blono.dev:"
note "  nameservers: $(ns_of)"
note "  blono.dev A:     $(dig +short A blono.dev | tr '\n' ' ')"
note "  www.blono.dev:   $(dig +short CNAME www.blono.dev | tr '\n' ' ')"
note "  MX records:      $(dig +short MX blono.dev | tr '\n' ' ')(none means no email to move)"
if [[ -n "$(dig +short DS blono.dev)" ]]; then
  warn "blono.dev has a DNSSEC DS record. Turn DNSSEC off at Porkbun and wait a day"
  warn "before continuing, or the nameserver change in stage 5 will take the site down."
  exit 1
fi
pass "no DNSSEC delegation, so the nameservers can change safely"
pause "Press Enter to start"

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Create the Worker from the GitHub repo (Workers Builds)"
say "Cloudflare will build and deploy the site on every push."
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages/create"
step "Choose 'Import a repository' (Continue with GitHub). If asked, install the"
step "  Cloudflare GitHub app with access to andrewgilliland/blono.dev only."
step "Select the blono.dev repository."
step "Worker / project name: ${BOLD}blono-dev${RESET}  (must match \"name\" in wrangler.jsonc,"
step "  or the build fails)."
step "Build command:  ${BOLD}npm run build${RESET}"
step "Deploy command: ${BOLD}npx wrangler deploy${RESET}"
step "If there's a non-production branch deploy command, keep ${BOLD}npx wrangler versions upload${RESET}"
step "Root directory: leave as the repo root."
step "Save and deploy."
printf '\n'
warn "main still has the old Next.js site, so a build of main will fail. That's"
warn "expected until #31 merges. Point production at the Astro branch for now:"
step "Worker → Settings → Build → Branch control → Production branch:"
step "  ${BOLD}migrate/astro-cloudflare${RESET}  → Save. (Part 2 switches it to main.)"
step "If no build has run on that branch, open Deployments/Builds and retry it,"
step "  or push any commit to migrate/astro-cloudflare."
note "If the build log shows a Node version below 22.12, add a build variable"
note "NODE_VERSION = 22 under Settings → Build → Variables, then retry."
printf '\n'
step "When the build succeeds, copy the Worker's URL from its overview page"
step "  (it looks like https://blono-dev.<your-subdomain>.workers.dev)."
while :; do
  ask WORKERS_DEV_URL "Paste the workers.dev URL:"
  WORKERS_DEV_URL="${WORKERS_DEV_URL%/}"
  [[ "$WORKERS_DEV_URL" =~ ^https://[a-z0-9.-]+\.workers\.dev$ ]] && break
  warn "That doesn't look like https://<name>.<subdomain>.workers.dev, try again."
done
write_env WORKERS_DEV_URL "$WORKERS_DEV_URL"

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Check the site on workers.dev"
say "Checking $WORKERS_DEV_URL ..."
printf '\n'
until check_site "$WORKERS_DEV_URL"; do
  printf '\n'
  warn "Some checks failed. If the deploy just finished, give it a minute."
  confirm "Re-run the checks?" || { SKIPPED+=("workers.dev checks (re-run: curl -I $WORKERS_DEV_URL)"); break; }
  printf '\n'
done
printf '\n'
note "This is the preview URL for #31's page-by-page comparison against production."
pause

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Add the blono.dev zone to Cloudflare"
open_url "https://dash.cloudflare.com/?to=/:account/add-site"
step "Enter ${BOLD}blono.dev${RESET}, let Cloudflare quick-scan the DNS records, and pick the ${BOLD}Free${RESET} plan."
step "Review the imported records. You should see exactly:"
note "    A      blono.dev   76.76.21.21           (Vercel)"
note "    CNAME  www         cname.vercel-dns.com  (Vercel)"
step "Add either one if it's missing, and delete anything else the scan invented."
step "Set ${BOLD}both to 'DNS only' (grey cloud)${RESET}, not Proxied, so Vercel keeps serving"
step "  the site and renewing its certificate until the cutover."
step "Continue. Skip the optional quick-start settings; the defaults are fine."
step "Cloudflare now shows ${BOLD}two nameservers${RESET} ending in .ns.cloudflare.com."
printf '\n'
while :; do
  ask CF_NS1 "First Cloudflare nameserver:"
  ask CF_NS2 "Second Cloudflare nameserver:"
  CF_NS1="${CF_NS1%.}"; CF_NS2="${CF_NS2%.}"
  [[ "$CF_NS1" == *.ns.cloudflare.com && "$CF_NS2" == *.ns.cloudflare.com ]] && break
  warn "Both should end in .ns.cloudflare.com, try again."
done
write_env CF_NS1 "$CF_NS1"
write_env CF_NS2 "$CF_NS2"

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Point blono.dev's nameservers at Cloudflare (Porkbun)"
say "This moves DNS to Cloudflare. The records you just copied still point at"
say "Vercel, so the site stays up. To undo, put Porkbun's nameservers back."
printf '\n'
if [[ "$(ns_of)" == *ns.cloudflare.com* ]]; then
  pass "blono.dev already uses Cloudflare's nameservers: $(ns_of)"
else
  confirm "Change blono.dev's nameservers at Porkbun now?" || { SKIPPED+=("Porkbun nameserver change, then re-run this wizard"); finish; exit 0; }
  open_url "https://porkbun.com/account/domainsSpeedy"
  step "Find blono.dev → Details → Authoritative Nameservers → Edit."
  step "Replace the four *.ns.porkbun.com entries with:"
  note "    $CF_NS1"
  note "    $CF_NS2"
  step "Save."
  step "Back in Cloudflare's blono.dev overview, click 'Check nameservers now'."
  pause "Press Enter once saved, and the wizard will watch for the change"
  printf '\n'
  say "Waiting for the new nameservers to show (checking every 30s, up to 30 min)..."
  for _ in $(seq 1 60); do
    [[ "$(ns_of)" == *ns.cloudflare.com* ]] && break
    printf '.'; sleep 30
  done
  printf '\n'
  if [[ "$(ns_of)" == *ns.cloudflare.com* ]]; then
    pass "blono.dev now uses Cloudflare's nameservers: $(ns_of)"
  else
    warn "Not visible yet: changes can take up to 24 hours. Cloudflare emails you when"
    warn "the zone is active; re-run this wizard then to confirm."
    SKIPPED+=("confirm the nameserver change (re-run this wizard)")
  fi
fi
[[ "$(status_of https://www.blono.dev/)" == 200 ]] \
  && pass "www.blono.dev still serves the current site" \
  || warn "www.blono.dev didn't return 200. Check the two DNS records in Cloudflare."
pause

finish
say "Next:"
step "Use $WORKERS_DEV_URL for #31's comparison, then merge the PR into main."
step "Then run ${BOLD}scripts/cloudflare-cutover.sh${RESET} to switch blono.dev over."
printf '\n'
}

run_wizard "$@"; exit
